function frame(now){
  controls?.update(now);
  const uiElapsed=Math.min(.25,Math.max(0,(now-lastFrame)/1000));lastFrame=now;
  const foreground=!document.hidden&&!focusSuspended&&!ui.busy;
  const campaignActive=foreground&&running&&!ui.screen;
  const chronicleActive=foreground&&inChronicles()&&chronicleBattle&&!chroniclePaused&&!chronicleFinished;
  const batch=simulationClock.advance(now,{suspended:!campaignActive&&!chronicleActive});
  if(batch.interrupted){clearActiveInput();simulationClock.reset(now);}
  for(let index=0;index<batch.steps;index++){
    const dt=batch.stepSeconds;
    if(running&&!ui.screen&&!ui.busy){
      state.playedSeconds+=dt;advanceMissionClock(dt);
      if(encounterRecovery)encounterRecovery=advanceEncounterRecovery(encounterRecovery,dt,{exploring:!battle});
      if(battle){tickBattle(battle,dt);drainEvents();if(battle.winner)finishBattle();}
    }
    updateExplorationBanter(dt,foreground&&running&&!ui.screen&&!ui.busy&&!battle&&!inChronicles());
    advanceChronicle(dt);
    world.update(running&&!ui.screen&&!ui.busy?dt:0,{render:index===batch.steps-1});
  }
  if(batch.steps===0)world.update(0);
  uiAccumulator+=uiElapsed;saveAccumulator+=batch.elapsed;
  if(uiAccumulator>.16){uiAccumulator=0;if(inChronicles())renderChronicleCombat();else if(running){renderHUD();if(battle)renderCombat();}}
  if(saveAccumulator>25){saveAccumulator=0;if(running&&!ui.screen&&!battle)autosave();}
  requestAnimationFrame(frame);
}
