    bombArmed: p.legacy ? null : p.bombArmed, rescue, survivor,
    lost: survivor === null ? null : survivor === 'ashley' ? 'kaidan' : 'ashley',
    extractionSite: p.legacy || survivor === null ? null : survivor === p.stgVolunteer ? 'aa-tower' : 'bomb' };
}

