import { createMissionProgress, normalizeMissionProgress, canCompleteMission } from './mission-progress.js';
import { createTalentState, normalizeTalents } from './campaign-talents.js';
import { initialInventory, normalizeInventory } from './loadout.js';
import { normalizeOperations, operationEffects, listOperations } from './operations.js';
import { CREW, CHAPTERS, CLASSES, ENCOUNTERS, EQUIPMENT } from './game-data.js';
import { COMMANDER_APPEARANCES, ORIGINS, PSYCHOLOGICAL_PROFILES } from './commander.js';
import { createStoryState, migrateStoryState, recordVisit, readTopic } from './story.js';
import { createAssignmentState, migrateAssignmentState } from './assignments.js';
import { initialCustomization, normalizeCustomization } from './customization.js';
import { createCampaignProgress, normalizeCampaignProgress, getCampaignMilestones } from './advance-progression.js';
import { getDestinationAccess } from './advance-travel-access.js';
import { createAdvanceFerosState, normalizeAdvanceFerosState, isAdvanceFerosUntouched, advanceFerosCompletionGate, ferosColonyReport } from './advance-feros.js';
import { createResolveCitadelState, normalizeResolveCitadelState, isResolveCitadelUntouched, transitionResolveCitadel, resolveCitadelEncounterVictory } from './resolve-citadel.js';
import { createResolveNoveriaState, normalizeResolveNoveriaState, isResolveNoveriaUntouched, resolveNoveriaCompletionGate } from './resolve-noveria.js';
import { createResolveVirmireState, normalizeResolveVirmireState, isResolveVirmireUntouched, resolveVirmireCompletionGate,
  getResolveVirmireAwayCrew, reconcileResolveVirmireParty, transitionResolveVirmire, resolveVirmireTravelGate } from './resolve-virmire.js';
import { createResolveOrigins, normalizeResolveOrigins } from './resolve-origins.js';
import { createResolveEndgameState, normalizeResolveEndgame } from './resolve-endgame.js';

export const SAVE_KEY = 'relay-chronicles.save.v1';
const SAVE_VERSION = 1;
const MODES = new Set(['wait', 'active']);
const DIFFICULTIES = new Set(['story', 'easy', 'normal', 'hard']);
const OWN = (object, key) => Object.prototype.hasOwnProperty.call(object, key);
const validOption = (options, key) => typeof key === 'string' && OWN(options, key);
const CHOICES = {
  feros: ['save', 'force'],
  noveria: ['release', 'destroy'],
  virmire: ['save-kaidan', 'save-ashley'],
  'citadel-finale': ['save-council', 'focus-sovereign'],
};
const DEFAULT_SETTINGS = { sound: true, volume: 0.35, reducedMotion: false, largeText: false };
const UPGRADE_STATS = { attack: 3, defense: 2, shield: 15 };
const FORBIDDEN_KEYS = new Set(['__proto__', 'prototype', 'constructor']);
const clone = value => JSON.parse(JSON.stringify(value));

export function newGame({ name = 'Shepard', classId = 'soldier', difficulty = 'normal', mode = 'wait', appearance = 'male', origin = 'spacer', psychologicalProfile = 'sole-survivor', customization } = {}) {
  return {
    version: SAVE_VERSION,
    name: typeof name === 'string' ? name.trim().slice(0, 24) || 'Shepard' : 'Shepard',
    appearance: validOption(COMMANDER_APPEARANCES, appearance) ? appearance : 'male',
    customization: normalizeCustomization(customization, validOption(COMMANDER_APPEARANCES, appearance) ? appearance : 'male')
      || initialCustomization(validOption(COMMANDER_APPEARANCES, appearance) ? appearance : 'male'),
    origin: validOption(ORIGINS, origin) ? origin : 'spacer',
    psychologicalProfile: validOption(PSYCHOLOGICAL_PROFILES, psychologicalProfile) ? psychologicalProfile : 'sole-survivor',
    classId: validOption(CLASSES, classId) ? classId : 'soldier',
    difficulty: DIFFICULTIES.has(difficulty) ? difficulty : 'normal',
    mode: MODES.has(mode) ? mode : 'wait',
    zone: 'normandy', party: ['shepard', 'kaidan', 'jenkins'], recruited: ['kaidan', 'jenkins'],
    lost: [], completed: [], cleared: [], collected: [], flags: {}, choices: {},
    story: createStoryState(), missionProgress: createMissionProgress(), talents: createTalentState(),
    assignments: createAssignmentState(), campaignProgress: createCampaignProgress(), advanceFeros: createAdvanceFerosState(),
    resolveCitadel: createResolveCitadelState(), resolveNoveria: createResolveNoveriaState(),
    resolveVirmire: createResolveVirmireState(), resolveOrigins: createResolveOrigins(), resolveEndgame: createResolveEndgameState(),
    inventory: initialInventory(), operations: normalizeOperations(undefined), trackedOperation: null,
    logs: [{ title: 'Départ', text: 'Le Normandy fait route vers Eden Prime.' }],
    xp: 0, credits: 250, medigel: 4, upgrades: {}, paragon: 0, renegade: 0,
    playedSeconds: 0, position: null, ending: false, settings: { ...DEFAULT_SETTINGS },
  };
}

export function unlockedZones(state) {
  const zones = ['normandy'];
  if (state.flags.briefed !== true) return zones;
  zones.push('eden-prime');
  if (!state.completed.includes('eden-prime')) return zones;
  zones.push('citadel');
  if (!state.completed.includes('citadel') || state.flags.spectre !== true) return zones;
  zones.push('therum', 'feros', 'noveria');
  if (['therum', 'feros', 'noveria'].filter(zone => state.completed.includes(zone)).length >= 2) zones.push('virmire');
  if (['therum', 'feros', 'noveria', 'virmire'].every(zone => state.completed.includes(zone))) zones.push('ilos');
  if (state.completed.includes('ilos') && zones.includes('ilos')) zones.push('citadel-finale');
  return zones;
}

export function zoneEncounters(zone) {
  return OWN(ENCOUNTERS, zone) ? [`${zone}:encounter-1`, `${zone}:encounter-2`, `${zone}:boss`] : [];
}

export function encounterIndex(id) {
  if (typeof id !== 'string') return -1;
  const zone = id.split(':')[0];
  return zoneEncounters(zone).indexOf(id);
}

export function objectiveReady(state, zone = state.zone) {
  if (!OWN(CHAPTERS, zone) || !unlockedZones(state).includes(zone) || state.completed.includes(zone)) return false;
  // Tali supplies the evidence against Saren. Garrus and Wrex can be recruited
  // independently; accepting their help is not a condition for the audience.
  if (zone === 'citadel') return state.recruited.includes('tali') && !state.lost.includes('tali')
    && (isResolveCitadelUntouched(state) || state.resolveCitadel?.legacy === true || state.resolveCitadel?.proof === true);
  const encounters = zoneEncounters(zone);
  return encounters.length > 0 && encounters.every(id => state.cleared.includes(id));
}

export function canStartEncounter(state, id) {
  const index = encounterIndex(id);
  if (index < 0) return { ok: false, reason: 'Rencontre inconnue.' };
  const zone = id.split(':')[0];
  if (state.cleared.includes(id)) return { ok: false, reason: 'Ce secteur est sécurisé.' };
  if (!unlockedZones(state).includes(zone)) return { ok: false, reason: 'Destination indisponible.' };
  if (state.zone !== zone) return { ok: false, reason: 'Rejoignez cette destination avant le combat.' };
  if (state.completed.includes(zone)) return { ok: false, reason: 'Cette mission est déjà accomplie.' };
  if (index > 0 && !zoneEncounters(zone).slice(0, index).every(previous => state.cleared.includes(previous))) {
    return { ok: false, reason: 'Sécurisez d’abord le secteur précédent.' };
  }
  return { ok: true };
}

export function addLog(state, title, text) {
  state.logs.unshift({ title: String(title).slice(0, 200), text: String(text).slice(0, 4000) });
  state.logs = state.logs.slice(0, 100);
}

/** A final dialogue confirmation authorizes departure once, with no reward. */
export function confirmCampaignBriefing(state) {
  const current = decodeSave({ format: 'relay-chronicles', version: SAVE_VERSION, state });
  if (!current) return { ok: false, reason: 'Progression invalide.' };
  if (current.zone !== 'normandy') return { ok: false, reason: 'Rejoignez le Normandy pour le briefing.' };
  if (current.flags.briefed === true) return { ok: true, changed: false };
  if (current.completed.length || current.cleared.length || current.story.visitedZones.includes('eden-prime'))
    return { ok: false, reason: 'Le premier briefing n’est plus disponible.' };
  state.flags = { ...current.flags, briefed: true };
  addLog(state, 'Briefing du Normandy', 'Anderson confirme la récupération de la balise. Kaidan et Jenkins accompagneront Shepard sur Eden Prime.');
  return { ok: true, changed: true };
}

/** Travel and the map share the same access explanation. No mutation happens
 * before the full save and the current timed-mission boundary are validated. */
export function canTravelCampaign(state, targetZone) {
  const current = decodeSave({ format: 'relay-chronicles', version: SAVE_VERSION, state });
  if (!current) return { ok: false, reason: 'Progression invalide.' };
  const deployment = resolveVirmireTravelGate(current, targetZone);
  if (!deployment.ok) return deployment;
  return getDestinationAccess(current, targetZone, { unlocked: unlockedZones(current) });
}

/** Commit only after the visual transition is ready. Repeating the arrival
 * cannot reset position, replay a receipt, or add a second journal entry. */
export function travelCampaign(state, targetZone) {
  const current = decodeSave({ format: 'relay-chronicles', version: SAVE_VERSION, state });
  if (!current) return { ok: false, reason: 'Progression invalide.' };
  const deployment = resolveVirmireTravelGate(current, targetZone);
  if (!deployment.ok) return deployment;
  const access = getDestinationAccess(current, targetZone, { unlocked: unlockedZones(current) });
  if (!access.ok) return access;
  if (current.zone === targetZone) return { ok: true, changed: false, firstVisit: false };
  const previousZone = current.zone;
  const firstVisit = !current.story.visitedZones.includes(targetZone);
  current.zone = targetZone;
  current.position = null;
  if (!recordVisit(current, targetZone)) return { ok: false, reason: 'Cette arrivée ne peut pas être enregistrée.' };
  if (previousZone === 'eden-prime' && targetZone === 'normandy'
    && current.completed.includes('eden-prime') && !current.campaignProgress.beaconReturned) {
    current.campaignProgress.beaconReturned = true;
    addLog(current, 'Vision de la balise', 'Après le contact avec la balise d’Eden Prime, Shepard et le commando ont rejoint le Normandy.');
  }
  if (previousZone === 'normandy' && ['therum', 'feros', 'noveria'].includes(targetZone)
    && current.flags.spectre === true && current.campaignProgress.commandDestination === null) {
    current.campaignProgress.commandDestination = targetZone;
    addLog(current, 'Commandement du Normandy', `Première piste choisie : ${CHAPTERS[targetZone].name}. Les enquêtes de Thérum, Féros et Novéria restent accessibles sans ordre imposé.`);
  }
  if (targetZone === 'eden-prime' && firstVisit) addLog(current, 'Déploiement Eden Prime', 'Shepard, Kaidan et Jenkins ont débarqué sur Eden Prime. Le commando découvre les conséquences de l’attaque.');
  if (!decodeSave({ format: 'relay-chronicles', version: SAVE_VERSION, state: current }))
    return { ok: false, reason: 'L’arrivée produirait une progression invalide.' };
  state.zone = current.zone;
  state.position = null;
  state.story = current.story;
  state.campaignProgress = current.campaignProgress;
  state.logs = current.logs;
  return { ok: true, changed: true, firstVisit };
}

export function trackCampaignMilestone(state, id = null) {
  const current = decodeSave({ format: 'relay-chronicles', version: SAVE_VERSION, state });
  if (!current) return { ok: false, reason: 'Progression invalide.' };
  if (id !== null && !getCampaignMilestones(current).some(entry => entry.id === id && entry.status === 'active'))
    return { ok: false, reason: 'Cette étape ne peut pas être suivie maintenant.' };
  if (current.campaignProgress.trackedMilestone === id) return { ok: true, changed: false };
  state.campaignProgress = { ...current.campaignProgress, trackedMilestone: id };
  if (id !== null) state.trackedOperation = null;
  return { ok: true, changed: true };
}

/** Resolve all Citadel effects against a validated detached snapshot. A stale
 * callback, invalid receipt or reward overflow leaves the campaign untouched. */
export function applyResolveCitadel(state, interactionId, choiceId) {
  const current = decodeSave({ format: 'relay-chronicles', version: SAVE_VERSION, state });
  if (!current) return { ok: false, reason: 'Progression invalide.' };
  const result = transitionResolveCitadel(current, interactionId, choiceId);
  if (!result.ok || !result.changed) return result;
  current.resolveCitadel = result.progress;
  if (interactionId === 'joker' && choiceId === 'report') {
    const read = readTopic(current, 'joker', 'eden-prime-report');
    if (!read.ok && !current.story.heard.includes('joker:eden-prime-report')) return read;
  }
  if (result.effect === 'recruit-tali' && !current.recruited.includes('tali')) {
    current.recruited.push('tali');
    addLog(current, 'Nouvel équipier', 'Tali rejoint votre commando après son sauvetage et la remise de la preuve.');
  }
  if (result.log) addLog(current, result.log.title, result.log.text);
  if (interactionId === 'fist') addLog(current, 'Sort de Fist', result.progress.fist === 'spared'
    ? 'Shepard a épargné Fist. L’aveu sur la ruelle a été conservé.'
    : `Fist a été abattu par ${result.progress.fist === 'wrex' ? 'Wrex, présent dans le groupe au combat' : 'Shepard, sans Wrex dans le groupe au combat'}. L’aveu sur la ruelle a été conservé.`);
  if (!decodeSave({ format: 'relay-chronicles', version: SAVE_VERSION, state: current }))
    return { ok: false, reason: 'Cette réponse produirait une progression invalide.' };
  state.resolveCitadel = current.resolveCitadel;
  state.recruited = current.recruited;
  state.logs = current.logs;
  state.story = current.story;
  return result;
}

/** Called only by the real battle victory controller; pure model callers can
 * inspect the encounter without awarding its adapted campaign rewards. */
export function winResolveCitadelEncounter(state, id) {
  const current = decodeSave({ format: 'relay-chronicles', version: SAVE_VERSION, state });
  if (!current) return { ok: false, reason: 'Progression invalide.' };
  const result = resolveCitadelEncounterVictory(current, id);
  if (!result.ok) return result;
  if (current.xp + result.xp > 1_000_000_000 || current.credits + result.credits > 1_000_000_000)
    return { ok: false, reason: 'La limite de récompense est atteinte.' };
  current.resolveCitadel = result.progress;
  current.xp += result.xp; current.credits += result.credits;
  addLog(current, result.log.title, result.log.text);
  if (!decodeSave({ format: 'relay-chronicles', version: SAVE_VERSION, state: current }))
    return { ok: false, reason: 'Cette victoire produirait une progression invalide.' };
  state.resolveCitadel = current.resolveCitadel;
  state.xp = current.xp; state.credits = current.credits; state.logs = current.logs;
  return result;
}

/** Assigning an STG volunteer or arming Virmire's bomb updates the field team
 * in the same validated transaction as its narrative receipt. */
export function applyResolveVirmireInteraction(state, id, choiceId) {
  const current = decodeSave({ format: 'relay-chronicles', version: SAVE_VERSION, state });
  if (!current) return { ok: false, reason: 'Progression invalide.' };
  const result = transitionResolveVirmire(current, id, choiceId);
  if (!result.ok) return result;
  if (result.progress) current.resolveVirmire = result.progress;
  const party = reconcileResolveVirmireParty(current);
  if (!party) return { ok: false, reason: 'Le groupe de terrain ne peut pas être réconcilié.' };
  current.party = party;
  if (result.log) addLog(current, result.log.title, result.log.text);
  if (!decodeSave({ format: 'relay-chronicles', version: SAVE_VERSION, state: current }))
    return { ok: false, reason: 'Cette affectation produirait une progression invalide.' };
  state.resolveVirmire = current.resolveVirmire; state.party = current.party; state.logs = current.logs;
  return result;
}

/** One authoritative transaction for the campaign's fixed supply containers. */
export function collectSupply(state, id) {
  const current = decodeSave({ format: 'relay-chronicles', version: SAVE_VERSION, state });
  if (!current) return { ok: false, reason: 'Progression invalide.' };
  const medical = id === 'normandy:medbay-restock';
  const validCache = typeof id === 'string' && OWN(ENCOUNTERS, current.zone) && id === `${current.zone}:cache`;
  if (medical ? current.zone !== 'normandy' : !validCache) return { ok: false, reason: 'Conteneur indisponible.' };
  if (current.collected.includes(id)) return { ok: false, reason: 'Ce conteneur est déjà vide.' };
  const credits = medical ? 0 : 100;
  if (current.credits + credits > 1_000_000_000) return { ok: false, reason: 'La limite de crédits est atteinte.' };
  const medigel = Math.min(9, current.medigel + (medical ? 2 : 1));
  state.collected = [...current.collected, id];
  state.credits = current.credits + credits;
  state.medigel = medigel;
  if (!medical) addLog(state, 'Ravitaillement', `${CHAPTERS[current.zone].name} : +100 crédits, une dose de médi-gel et des données récupérées.`);
  return { ok: true, credits, medigel: medigel - current.medigel };
}

export function recruit(state, id) {
  if (!OWN(CREW, id) || id === 'shepard' || state.lost.includes(id) || state.recruited.includes(id)) return false;
  const allowed = id === 'ashley'
    ? state.zone === 'eden-prime' && state.cleared.includes('eden-prime:encounter-1')
    : id === 'liara'
      ? state.zone === 'therum' && state.completed.includes('therum')
      // Completing the audience does not prevent a later recruitment visit.
      : ['garrus', 'tali', 'wrex'].includes(id) && state.zone === 'citadel' && unlockedZones(state).includes('citadel');
  if (!allowed) return false;
  if (!isResolveCitadelUntouched(state) && state.resolveCitadel?.legacy !== true) {
    // Modern Tali recruitment is inseparable from the evidence receipt and is
    // committed by applyResolveCitadel; retain the untouched historical API.
    if (id === 'tali' || id === 'garrus' && state.resolveCitadel?.clinic !== true) return false;
  }
  state.recruited.push(id);
  addLog(state, 'Nouvel équipier', `${CREW[id].name} rejoint votre commando.`);
  return true;
}

export function availableCrew(state) {
  const away = getResolveVirmireAwayCrew(state);
  return state.recruited.filter(id => OWN(CREW, id) && !state.lost.includes(id) && !['shepard', 'jenkins'].includes(id) && !away.includes(id));
}

export function setSquad(state, ids) {
  if (state.zone !== 'normandy' || !Array.isArray(ids) || ids.length !== 2 || new Set(ids).size !== 2) return false;
  const away = getResolveVirmireAwayCrew(state);
  if (!ids.every(id => id !== 'shepard' && OWN(CREW, id) && state.recruited.includes(id) && !state.lost.includes(id) && !away.includes(id))) return false;
  state.party = ['shepard', ...ids];
  return true;
}

export function winEncounter(state, id) {
  if (!canStartEncounter(state, id).ok) return false;
  const legacyNoveria = id.startsWith('noveria:') && isResolveNoveriaUntouched(state);
  state.cleared.push(id);
  // Native historical callers can still cross the retained chapter boundary;
  // player-facing controllers enforce the new Port Hanshan pass beforehand.
  if (legacyNoveria) state.resolveNoveria = { ...createResolveNoveriaState(), legacy: true };
  state.xp += 65;
  state.credits += 85;
  if (id === 'eden-prime:encounter-1') {
    state.flags.jenkinsLost = true;
    if (!state.lost.includes('jenkins')) state.lost.push('jenkins');
    recruit(state, 'ashley');
    state.party = ['shepard', 'kaidan', 'ashley'];
    addLog(state, 'Eden Prime', 'Jenkins a été tué pendant la descente. Ashley Williams rejoint le commando après l’attaque de sa garnison.');
  }
  return true;
}

export function completeZone(state, zone, choice = null) {
  if (state.zone !== zone || !objectiveReady(state, zone) || !canCompleteMission(state, zone)) return false;
  if (OWN(CHOICES, zone) ? !CHOICES[zone].includes(choice) : choice !== null && choice !== undefined) return false;
  const legacyFeros = zone === 'feros' && isAdvanceFerosUntouched(state);
  const legacyVirmire = zone === 'virmire' && isResolveVirmireUntouched(state);
  const legacyNoveria = zone === 'noveria' && isResolveNoveriaUntouched(state);
  if (zone === 'noveria' && !legacyNoveria && !resolveNoveriaCompletionGate(state).ok) return false;
  if (zone === 'virmire' && !legacyVirmire && !resolveVirmireCompletionGate(state, choice).ok) return false;
  if (zone === 'feros' && !legacyFeros && !advanceFerosCompletionGate(state).ok) return false;
  if (zone === 'feros' && !legacyFeros) {
    const colony = ferosColonyReport(state);
    if (colony.known && choice !== colony.completionChoice) return false;
  }
  state.completed.push(zone);
  // Preserve the historical native chapter boundary when none of the new
  // Feros interactions has been started. Do not invent colonist outcomes.
  if (legacyFeros) state.advanceFeros = { ...createAdvanceFerosState(), legacy: true };
  if (legacyVirmire) state.resolveVirmire = { ...createResolveVirmireState(), legacy: true };
  if (legacyNoveria) state.resolveNoveria = { ...createResolveNoveriaState(), legacy: true };
  state.xp += CHAPTERS[zone].reward;
  state.credits += 180;
  state.medigel = Math.min(9, state.medigel + 2);
  if (OWN(CHOICES, zone)) state.choices[zone] = choice;
  if (zone === 'citadel') state.flags.spectre = true;
  if (zone === 'therum') recruit(state, 'liara');
  if (zone === 'feros') state[choice === 'save' ? 'paragon' : 'renegade'] += 20;
  if (zone === 'noveria') state[choice === 'release' ? 'paragon' : 'renegade'] += 20;
  if (zone === 'virmire') {
    const lost = choice === 'save-kaidan' ? 'ashley' : 'kaidan';
    if (!state.lost.includes(lost)) state.lost.push(lost);
    state.party = state.party.filter(id => id !== lost);
    for (const id of availableCrew(state)) if (state.party.length < 3 && !state.party.includes(id)) state.party.push(id);
  }
  if (zone === 'citadel-finale') {
    state.ending = true;
    state[choice === 'save-council' ? 'paragon' : 'renegade'] += 20;
  }
  addLog(state, CHAPTERS[zone].name, `Objectif accompli${choice ? ` · décision : ${choice}` : ''}.`);
  return true;
}

export function upgradePrice(state, itemId) {
  const item = EQUIPMENT.find(candidate => candidate.id === itemId);
  if (!item) return 0;
  return Math.round(item.cost * (item.stat === 'medigel' ? 1 - operationEffects(state).medicalDiscount : 1));
}

export function buyUpgrade(state, actorId, itemId) {
  if (!['normandy', 'citadel'].includes(state.zone) || !unlockedZones(state).includes(state.zone)) return { ok: false, reason: 'Rejoignez une armurerie.' };
  if (!OWN(CREW, actorId) || state.lost.includes(actorId) || (actorId !== 'shepard' && !state.recruited.includes(actorId))) return { ok: false, reason: 'Équipier indisponible.' };
  const item = EQUIPMENT.find(candidate => candidate.id === itemId);
  if (!item) return { ok: false, reason: 'Équipement inconnu.' };
  if (!Number.isSafeInteger(state.credits) || state.credits < 0 || state.credits > 1_000_000_000
    || !Number.isInteger(state.medigel) || state.medigel < 0 || state.medigel > 9) return { ok: false, reason: 'Réserves invalides.' };
  const price = upgradePrice(state, itemId);
  if (state.credits < price) return { ok: false, reason: 'Crédits insuffisants.' };
  if (item.stat === 'medigel') {
    if (state.medigel >= 9) return { ok: false, reason: 'Réserve complète.' };
    state.medigel += 1;
  } else {
    const existing = state.upgrades[actorId] || {};
    const count = existing[`${item.stat}Count`] || 0;
    if (count >= 5) return { ok: false, reason: 'Amélioration maximale atteinte.' };
    state.upgrades[actorId] = {
      ...existing,
      [item.stat]: (existing[item.stat] || 0) + item.value,
      [`${item.stat}Count`]: count + 1,
    };
  }
  state.credits -= price;
  return { ok: true };
}

export function encodeSave(state) {
  // Check the actual object before JSON can call toJSON/getters or erase an
